let db:IDBDatabase;

const topStatLeaderDBPromise:Promise<IDBDatabase> = new Promise((resolve, reject) => {
    let request: IDBOpenDBRequest = indexedDB.open("skaterStatLeaderDatabase", 2);

    request.onupgradeneeded = function(event:IDBVersionChangeEvent){
        db = (event.target as IDBOpenDBRequest).result;

        if(!db.objectStoreNames.contains("topStatLeaderStore")){
            const topStatLeaderStore = db.createObjectStore("topStatLeaderStore", {keyPath:"statIndicator"});
            topStatLeaderStore.createIndex("statIndicator", "statIndicator", {unique:false});
        }
    };
    request.onsuccess = function(event:Event){
        db = (event.target as IDBOpenDBRequest).result;
        console.log("Database connection established"); 
        resolve(db);
    };
    request.onerror = function(event:Event){
        console.error("Database error: " + (event.target as IDBOpenDBRequest).error?.message);
        reject((event.target as IDBOpenDBRequest).error);
    };
});

export { topStatLeaderDBPromise };
